    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn empty_double_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn empty_single_quoted_value() {
        let vars = EnvFileParser::parse("KEY=''").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_double_then_single() {
        // Starts with " ends with ' — not a matched pair, so kept as-is
        let vars = EnvFileParser::parse(r#"KEY="value'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
    }

    #[test]
    fn mismatched_quotes_single_then_double() {
        let vars = EnvFileParser::parse(r#"KEY='value""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"'value""#.to_string()));
    }

    #[test]
    fn single_double_quote_only() {
        // Just a lone " is not a matched pair
        let vars = EnvFileParser::parse(r#"KEY=""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"""#.to_string()));
    }

    #[test]
    fn single_single_quote_only() {
        let vars = EnvFileParser::parse("KEY='").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes() {
        let vars = EnvFileParser::parse(r#"KEY='he said "hello"'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"he said "hello""#.to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes() {
        let vars = EnvFileParser::parse(r#"KEY="it's fine""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's fine".to_string()));
    }

    #[test]
    fn quotes_in_middle_of_value_not_stripped() {
        // Quotes that don't surround the entire value stay as-is
        let vars = EnvFileParser::parse(r#"KEY=some"quoted"value"#).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"some"quoted"value"#.to_string())
        );
    }

    #[test]
    fn triple_double_quotes() {
        // """value""" — outer pair stripped, inner quotes remain
        let vars = EnvFileParser::parse(r#"KEY="""value""""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"""value"""#.to_string()));
    }

    // --- Escaped characters ---

    #[test]
    fn backslash_n_in_double_quotes_kept_literal() {
        // Parser does not interpret escape sequences — \n stays as literal backslash + n
        let vars = EnvFileParser::parse(r#"KEY="line1\nline2""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"line1\nline2".to_string()));
    }

    #[test]
    fn backslash_t_in_double_quotes_kept_literal() {
        let vars = EnvFileParser::parse(r#"KEY="col1\tcol2""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"col1\tcol2".to_string()));
    }

    #[test]
    fn escaped_double_quote_inside_double_quotes_not_handled() {
        // The parser doesn't handle \" escapes — it sees the first matching "
        // Input: KEY="say \"hello\""
        // After trimming, value is: "say \"hello\""
        // starts_with('"') and ends_with('"') => true, so outer quotes stripped
        let vars = EnvFileParser::parse(r#"KEY="say \"hello\"""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say \"hello\""#.to_string()));
    }

    #[test]
    fn backslash_in_unquoted_value() {
        let vars = EnvFileParser::parse(r"KEY=C:\Users\name").unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"C:\Users\name".to_string()));
    }

    #[test]
    fn backslash_in_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="C:\Users\name""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"C:\Users\name".to_string()));
    }

    // --- Whitespace edge cases ---

    #[test]
    fn leading_whitespace_on_line_is_trimmed() {
        let vars = EnvFileParser::parse("   KEY=value").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn trailing_whitespace_on_line_trimmed_from_value() {
        // Line is trimmed, so trailing spaces are removed from the raw line,
        // but the value portion is also trimmed
        let vars = EnvFileParser::parse("KEY=value   ").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn whitespace_only_line_skipped() {
        let vars = EnvFileParser::parse("   \n\nKEY=value\n   \n").unwrap();
        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn tab_around_equals() {
        let vars = EnvFileParser::parse("KEY\t=\tvalue").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn spaces_inside_quoted_value_preserved() {
        let vars = EnvFileParser::parse(r#"KEY="  spaced  ""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaced  ".to_string()));
    }

    #[test]
    fn spaces_around_unquoted_value_trimmed() {
        let vars = EnvFileParser::parse("KEY=  hello world  ").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"hello world".to_string()));
    }

    // --- Special value content ---

    #[test]
    fn value_with_hash_not_treated_as_comment() {
        // Inline comments are NOT stripped — the hash is part of the value
        let vars = EnvFileParser::parse("COLOR=#ffffff").unwrap();
        assert_eq!(vars.get("COLOR"), Some(&"#ffffff".to_string()));
    }

    #[test]
    fn value_with_inline_hash_kept() {
        let vars = EnvFileParser::parse("KEY=value # this is not stripped").unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is not stripped".to_string())
        );
    }

    #[test]
    fn value_with_multiple_equals() {
        let vars = EnvFileParser::parse("BASE64=dGVzdA==").unwrap();
        assert_eq!(vars.get("BASE64"), Some(&"dGVzdA==".to_string()));
    }

    #[test]
    fn value_with_unicode() {
        let vars = EnvFileParser::parse("GREETING=héllo wörld").unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"héllo wörld".to_string()));
    }

    #[test]
    fn value_with_unicode_in_quotes() {
        let vars = EnvFileParser::parse(r#"EMOJI="🚀 launch""#).unwrap();
        assert_eq!(vars.get("EMOJI"), Some(&"🚀 launch".to_string()));
    }

    // --- Key edge cases ---

    #[test]
    fn key_with_underscores_and_numbers() {
        let vars = EnvFileParser::parse("MY_VAR_2=value").unwrap();
        assert_eq!(vars.get("MY_VAR_2"), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_dots() {
        let vars = EnvFileParser::parse("spring.datasource.url=jdbc:mysql://localhost").unwrap();
        assert_eq!(
            vars.get("spring.datasource.url"),
            Some(&"jdbc:mysql://localhost".to_string())
        );
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn key_is_just_equals() {
        // Line "=value" — key is empty string
        let vars = EnvFileParser::parse("=value").unwrap();
        assert_eq!(vars.get(""), Some(&"value".to_string()));
    }

    // --- Comment edge cases ---

    #[test]
    fn comment_with_equals_sign_ignored() {
        let vars = EnvFileParser::parse("# DATABASE_URL=secret").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn comment_with_leading_whitespace() {
        // Line "  # comment" is trimmed to "# comment", then skipped
        let vars = EnvFileParser::parse("  # comment\nKEY=val").unwrap();
        assert_eq!(vars.len(), 1);
    }

    // --- load / load_optional ---

    #[test]
    fn load_reads_file_from_disk() {
        let dir = tempfile::TempDir::new().unwrap();
        let env_path = dir.path().join(".env");
        std::fs::write(&env_path, "FROM_FILE=yes\n").unwrap();

        let vars = EnvFileParser::load(&env_path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"yes".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/no/such/file/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::TempDir::new().unwrap();
        let env_path = dir.path().join(".env");
        std::fs::write(&env_path, "OPT=yes").unwrap();

        let vars = EnvFileParser::load_optional(&env_path).unwrap();
        assert_eq!(vars.get("OPT"), Some(&"yes".to_string()));
    }

    // --- Empty / degenerate inputs ---

    #[test]
    fn completely_empty_input() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_and_blanks() {
        let content = "# comment\n\n# another\n   \n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn windows_line_endings() {
        let content = "KEY1=val1\r\nKEY2=val2\r\n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY1"), Some(&"val1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"val2".to_string()));
    }
}

